+
+.primary-nav {
+  justify-self: center;
+}
+.primary-nav__list {
+  list-style: none;
+  margin: 0;
+  padding: 0;
+  display: none;
+  gap: 4px;
+}
+@media (min-width: 900px) {
+  .primary-nav__list {
+    display: flex;
+  }
+}
+.primary-nav__list a {
