+}
+.primary-nav__list a[aria-current="page"] {
+  background: var(--color-ink);
+  color: #fff;
+}
+
+.header-actions {
+  display: flex;
+  align-items: center;
+  gap: 4px;
+}
+.icon-btn {
+  position: relative;
+  width: 40px;
+  height: 40px;
+  border-radius: 999px;
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  color: var(--color-ink);
+  transition: background 0.18s var(--ease);
+}
+.icon-btn:hover {
+  background: var(--color-surface-2);
+}
+.icon-btn svg {
+  width: 20px;
+  height: 20px;
+}
+.icon-btn .cart-count {
+  position: absolute;
+  top: 4px;
+  right: 4px;
+  min-width: 18px;
+  height: 18px;
+  padding: 0 5px;
+  border-radius: 999px;
+  background: var(--color-accent);
+  color: #fff;
+  font-size: 11px;
+  font-weight: 700;
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  line-height: 1;
+}
+.menu-toggle {
+  display: inline-flex;
+}
+@media (min-width: 900px) {
+  .menu-toggle {
+    display: none;
+  }
+}
+
+/* Mobile drawer */
+.mobile-nav {
+  border-top: 1px solid var(--color-line);
+  background: var(--color-bg);
+}
+.mobile-nav__list {
+  list-style: none;
+  margin: 0;
+  padding: var(--space-3) var(--shell-pad) var(--space-5);
+  display: flex;
+  flex-direction: column;
+  gap: 2px;
+}
+.mobile-nav a {
+  display: block;
+  padding: 14px 12px;
+  border-radius: 10px;
+  text-decoration: none;
+  font-weight: 500;
+  color: var(--color-ink-soft);
+}
+.mobile-nav a:hover {
+  background: var(--color-surface-2);
+}
+
+/* ============================================================
+   Hero
+   ============================================================ */
+.hero {
+  padding: clamp(28px, 4vw, 56px) 0 clamp(40px, 6vw, 72px);
+}
+.hero__grid {
+  display: grid;
+  gap: var(--space-5);
+  grid-template-columns: 1fr;
+}
+@media (min-width: 960px) {
+  .hero__grid {
+    grid-template-columns: 1.05fr 1fr;
+    gap: var(--space-7);
+    align-items: stretch;
+  }
+}
+.hero__copy {
+  display: flex;
+  flex-direction: column;
+  justify-content: center;
+  padding: 8px 0;
+}
+.eyebrow {
+  display: inline-flex;
+  align-items: center;
+  gap: 8px;
+  font-size: 12px;
+  font-weight: 600;
+  letter-spacing: 0.12em;
+  text-transform: uppercase;
