+  margin-bottom: var(--space-4);
+}
+.eyebrow::before {
+  content: "";
+  width: 24px;
+  height: 1px;
+  background: currentColor;
+}
+.hero__title {
+  font-family: var(--font-serif);
+  font-weight: 500;
+  font-size: clamp(40px, 6.4vw, 76px);
+  line-height: 1.02;
+  letter-spacing: -0.02em;
+  margin: 0 0 var(--space-4);
+  color: var(--color-ink);
+}
+.hero__title em {
+  font-style: italic;
+  color: var(--color-accent);
+  font-weight: 400;
+}
+.hero__lede {
