+}
+.deal--feature .btn--primary {
+  background: #f6f1e6;
+  color: var(--color-ink);
+}
+.deal--feature .btn--primary:hover {
+  background: #fff;
+}
+.deal__price {
+  display: flex;
+  align-items: baseline;
+  gap: 10px;
+}
+.deal__price .now {
+  font-family: var(--font-serif);
+  font-size: 30px;
+  font-weight: 500;
+  letter-spacing: -0.01em;
+}
+.deal__price .was {
+  text-decoration: line-through;
+  color: var(--color-muted);
+}
+.deal__bg {
+  position: absolute;
+  right: -40px;
+  bottom: -40px;
+  width: 220px;
+  height: 220px;
+  border-radius: 50%;
