+  --color-line-strong: #c8c5bb;
+  --color-accent: #b94d2a;     /* terracotta */
+  --color-accent-ink: #7e2f15;
+  --color-sale: #b03b2a;
+  --color-success: #2e6b3e;
+  --color-focus: #1a3fa3;
+
+  /* Type */
+  --font-sans: "Inter", system-ui, -apple-system, "Segoe UI", Roboto,
+    "Helvetica Neue", Arial, sans-serif;
+  --font-serif: "Fraunces", "Georgia", "Times New Roman", serif;
+
+  /* Spacing */
+  --space-1: 4px;
+  --space-2: 8px;
+  --space-3: 12px;
+  --space-4: 16px;
+  --space-5: 24px;
+  --space-6: 32px;
+  --space-7: 48px;
+  --space-8: 64px;
+  --space-9: 96px;
+
+  /* Radius */
+  --radius-sm: 6px;
+  --radius-md: 10px;
+  --radius-lg: 18px;
+  --radius-xl: 28px;
+
+  /* Layout */
+  --maxw: 1240px;
+  --shell-pad: clamp(16px, 4vw, 40px);
+
+  /* Motion */
+  --ease: cubic-bezier(0.2, 0.7, 0.2, 1);
+}
+
+* {
+  box-sizing: border-box;
+}
+html {
+  -webkit-text-size-adjust: 100%;
+  scroll-behavior: smooth;
+}
+@media (prefers-reduced-motion: reduce) {
+  html {
+    scroll-behavior: auto;
+  }
+  * {
+    animation: none !important;
+    transition: none !important;
+  }
+}
+
+body {
+  margin: 0;
+  font-family: var(--font-sans);
+  font-size: 16px;
+  line-height: 1.55;
+  color: var(--color-ink);
+  background: var(--color-bg);
+  -webkit-font-smoothing: antialiased;
+  text-rendering: optimizeLegibility;
+}
+
+img,
+svg {
+  display: block;
+  max-width: 100%;
+}
+
+button {
+  font: inherit;
+  color: inherit;
+  background: none;
+  border: 0;
+  cursor: pointer;
+}
+
+a {
+  color: inherit;
+  text-decoration-thickness: 1px;
+  text-underline-offset: 3px;
+}
+
+:focus {
+  outline: none;
+}
+:focus-visible {
+  outline: 2px solid var(--color-focus);
+  outline-offset: 2px;
+  border-radius: 4px;
+}
+
+.skip-link {
+  position: absolute;
+  left: var(--space-4);
+  top: -100px;
+  background: var(--color-ink);
+  color: #fff;
+  padding: 10px 14px;
+  border-radius: 6px;
+  z-index: 1000;
+  text-decoration: none;
+  font-weight: 600;
+}
+.skip-link:focus {
+  top: var(--space-4);
+}
+
+.shell {
+  width: 100%;
+  max-width: var(--maxw);
+  margin-inline: auto;
+  padding-inline: var(--shell-pad);
+}
+
+.sr-only {
+  position: absolute;
+  width: 1px;
+  height: 1px;
+  padding: 0;
+  margin: -1px;
+  overflow: hidden;
+  clip: rect(0, 0, 0, 0);
+  white-space: nowrap;
+  border: 0;
+}
+
+/* ============================================================
+   Top announcement bar
+   ============================================================ */
+.announce {
+  background: var(--color-ink);
+  color: #f3efe7;
+  font-size: 13px;
+  letter-spacing: 0.02em;
+}
+.announce__inner {
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  gap: var(--space-4);
+  padding: 10px var(--shell-pad);
+  text-align: center;
+}
+.announce__sep {
+  color: var(--color-muted-2);
+  display: none;
+}
+@media (min-width: 720px) {
+  .announce__sep {
+    display: inline;
+  }
+}
+.announce__item {
+  display: inline-flex;
+  align-items: center;
+  gap: 8px;
+}
+.announce a {
+  color: inherit;
+}
+
+/* ============================================================
+   Header / nav
+   ============================================================ */
+.header {
+  position: sticky;
+  top: 0;
+  z-index: 50;
+  background: color-mix(in srgb, var(--color-bg) 88%, transparent);
+  backdrop-filter: saturate(140%) blur(10px);
+  border-bottom: 1px solid var(--color-line);
+}
+.header__inner {
+  display: grid;
+  grid-template-columns: auto 1fr auto;
+  align-items: center;
+  gap: var(--space-4);
+  height: 72px;
+}
+.brand {
+  font-family: var(--font-serif);
+  font-weight: 600;
+  font-size: 26px;
+  letter-spacing: -0.01em;
+  line-height: 1;
+  text-decoration: none;
+}
+.brand sup {
+  font-size: 10px;
+  color: var(--color-muted);
+  font-weight: 500;
+  margin-left: 4px;
+  vertical-align: super;
+}
+
+.primary-nav {
+  justify-self: center;
+}
+.primary-nav__list {
+  list-style: none;
+  margin: 0;
+  padding: 0;
+  display: none;
+  gap: 4px;
+}
+@media (min-width: 900px) {
+  .primary-nav__list {
+    display: flex;
+  }
+}
+.primary-nav__list a {
+  display: inline-block;
+  padding: 10px 14px;
+  border-radius: 999px;
+  text-decoration: none;
+  font-weight: 500;
+  font-size: 14.5px;
+  color: var(--color-ink-soft);
+  transition: background 0.18s var(--ease), color 0.18s var(--ease);
+}
+.primary-nav__list a:hover {
+  background: var(--color-surface-2);
+  color: var(--color-ink);
+}
+.primary-nav__list a[aria-current="page"] {
+  background: var(--color-ink);
+  color: #fff;
+}
+
+.header-actions {
+  display: flex;
+  align-items: center;
+  gap: 4px;
+}
+.icon-btn {
+  position: relative;
+  width: 40px;
+  height: 40px;
+  border-radius: 999px;
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  color: var(--color-ink);
+  transition: background 0.18s var(--ease);
+}
+.icon-btn:hover {
+  background: var(--color-surface-2);
+}
+.icon-btn svg {
+  width: 20px;
+  height: 20px;
+}
+.icon-btn .cart-count {
+  position: absolute;
+  top: 4px;
+  right: 4px;
+  min-width: 18px;
+  height: 18px;
+  padding: 0 5px;
+  border-radius: 999px;
+  background: var(--color-accent);
+  color: #fff;
+  font-size: 11px;
+  font-weight: 700;
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  line-height: 1;
+}
+.menu-toggle {
+  display: inline-flex;
+}
+@media (min-width: 900px) {
+  .menu-toggle {
+    display: none;
+  }
+}
+
+/* Mobile drawer */
+.mobile-nav {
+  border-top: 1px solid var(--color-line);
+  background: var(--color-bg);
+}
+.mobile-nav__list {
+  list-style: none;
+  margin: 0;
+  padding: var(--space-3) var(--shell-pad) var(--space-5);
+  display: flex;
+  flex-direction: column;
+  gap: 2px;
+}
+.mobile-nav a {
+  display: block;
+  padding: 14px 12px;
+  border-radius: 10px;
+  text-decoration: none;
+  font-weight: 500;
+  color: var(--color-ink-soft);
+}
+.mobile-nav a:hover {
+  background: var(--color-surface-2);
+}
+
+/* ============================================================
+   Hero
+   ============================================================ */
+.hero {
+  padding: clamp(28px, 4vw, 56px) 0 clamp(40px, 6vw, 72px);
+}
+.hero__grid {
+  display: grid;
+  gap: var(--space-5);
+  grid-template-columns: 1fr;
+}
+@media (min-width: 960px) {
+  .hero__grid {
+    grid-template-columns: 1.05fr 1fr;
+    gap: var(--space-7);
+    align-items: stretch;
+  }
+}
+.hero__copy {
+  display: flex;
+  flex-direction: column;
+  justify-content: center;
+  padding: 8px 0;
+}
+.eyebrow {
+  display: inline-flex;
+  align-items: center;
+  gap: 8px;
+  font-size: 12px;
+  font-weight: 600;
+  letter-spacing: 0.12em;
+  text-transform: uppercase;
+  color: var(--color-muted);
+  margin-bottom: var(--space-4);
+}
+.eyebrow::before {
+  content: "";
+  width: 24px;
+  height: 1px;
+  background: currentColor;
+}
+.hero__title {
+  font-family: var(--font-serif);
+  font-weight: 500;
+  font-size: clamp(40px, 6.4vw, 76px);
+  line-height: 1.02;
+  letter-spacing: -0.02em;
+  margin: 0 0 var(--space-4);
+  color: var(--color-ink);
+}
+.hero__title em {
+  font-style: italic;
+  color: var(--color-accent);
+  font-weight: 400;
+}
+.hero__lede {
+  font-size: clamp(16px, 1.5vw, 18px);
+  color: var(--color-muted);
+  max-width: 52ch;
+  margin: 0 0 var(--space-6);
+}
+.hero__cta {
+  display: flex;
+  flex-wrap: wrap;
+  gap: var(--space-3);
+  margin-bottom: var(--space-6);
+}
+.hero__meta {
+  display: flex;
+  flex-wrap: wrap;
+  gap: var(--space-5);
+  padding-top: var(--space-5);
+  border-top: 1px solid var(--color-line);
+}
+.hero__meta dt {
+  font-size: 12px;
+  letter-spacing: 0.08em;
+  text-transform: uppercase;
+  color: var(--color-muted);
+  margin-bottom: 4px;
+}
+.hero__meta dd {
+  margin: 0;
+  font-family: var(--font-serif);
+  font-weight: 500;
+  font-size: 22px;
+  letter-spacing: -0.01em;
+}
+
+.hero__visual {
+  position: relative;
+  border-radius: var(--radius-xl);
+  overflow: hidden;
+  aspect-ratio: 4 / 5;
+  background: linear-gradient(160deg, #d9d3c5 0%, #c0bba9 60%, #aaa491 100%);
+  min-height: 420px;
+}
+.hero__visual::after {
+  content: "";
+  position: absolute;
+  inset: 0;
+  background: radial-gradient(
+      120% 80% at 80% 0%,
+      rgba(255, 255, 255, 0.35),
+      transparent 60%
+    ),
+    radial-gradient(80% 60% at 10% 100%, rgba(20, 21, 15, 0.25), transparent 70%);
+  pointer-events: none;
+}
+.hero__visual-inner {
+  position: absolute;
+  inset: 0;
+  display: grid;
+  place-items: center;
+  padding: var(--space-6);
+}
+.hero__chip {
+  position: absolute;
+  background: rgba(255, 255, 255, 0.92);
+  backdrop-filter: blur(6px);
+  border-radius: 14px;
+  padding: 12px 14px;
+  font-size: 13px;
+  display: flex;
+  align-items: center;
+  gap: 10px;
+  box-shadow: 0 10px 30px -12px rgba(20, 21, 15, 0.25);
+  border: 1px solid rgba(255, 255, 255, 0.6);
+}
+.hero__chip strong {
+  font-weight: 600;
+}
+.hero__chip--tl {
+  top: 20px;
+  left: 20px;
+}
+.hero__chip--br {
+  bottom: 24px;
+  right: 24px;
+}
+.hero__chip__dot {
+  width: 8px;
+  height: 8px;
+  border-radius: 50%;
+  background: var(--color-success);
+  box-shadow: 0 0 0 4px rgba(46, 107, 62, 0.18);
+}
+.hero__product-card {
+  background: rgba(255, 255, 255, 0.96);
+  border-radius: var(--radius-lg);
+  padding: 18px;
+  width: min(280px, 80%);
+  box-shadow: 0 30px 60px -25px rgba(20, 21, 15, 0.35);
+  display: flex;
+  flex-direction: column;
+  gap: 8px;
+}
+.hero__product-card .pcard__img {
+  aspect-ratio: 1 / 1;
+  border-radius: 12px;
+  background: linear-gradient(135deg, #efe5d2, #d9c9a6);
+  display: grid;
+  place-items: center;
+}
+.hero__product-card .pcard__name {
+  font-family: var(--font-serif);
+  font-size: 18px;
+  font-weight: 500;
+  margin: 6px 0 0;
+}
+.hero__product-card .pcard__row {
+  display: flex;
+  justify-content: space-between;
+  align-items: center;
+  font-size: 13px;
+  color: var(--color-muted);
+}
+.hero__product-card .pcard__row strong {
+  color: var(--color-ink);
+  font-weight: 600;
+}
+
+/* Buttons */
+.btn {
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  gap: 8px;
+  height: 48px;
+  padding: 0 22px;
+  border-radius: 999px;
+  font-weight: 600;
+  font-size: 15px;
+  text-decoration: none;
+  border: 1px solid transparent;
+  transition: transform 0.15s var(--ease), background 0.18s var(--ease),
+    color 0.18s var(--ease), border-color 0.18s var(--ease);
+  white-space: nowrap;
+}
+.btn:active {
+  transform: translateY(1px);
+}
+.btn--primary {
+  background: var(--color-ink);
+  color: #fff;
+}
+.btn--primary:hover {
+  background: var(--color-ink-soft);
+}
+.btn--secondary {
+  background: transparent;
+  border-color: var(--color-line-strong);
+  color: var(--color-ink);
+}
+.btn--secondary:hover {
+  background: var(--color-surface);
+  border-color: var(--color-ink);
+}
+.btn--accent {
+  background: var(--color-accent);
+  color: #fff;
+}
+.btn--accent:hover {
+  background: var(--color-accent-ink);
+}
+.btn--sm {
+  height: 38px;
+  padding: 0 16px;
+  font-size: 13.5px;
+}
+.btn--ghost {
+  background: transparent;
+  color: var(--color-ink);
+}
+.btn--ghost:hover {
+  background: var(--color-surface-2);
+}
+
+/* ============================================================
+   Marquee / brand strip
+   ============================================================ */
+.strip {
+  border-block: 1px solid var(--color-line);
+  background: var(--color-surface);
+}
+.strip__inner {
+  display: flex;
+  align-items: center;
+  gap: clamp(24px, 5vw, 56px);
+  flex-wrap: wrap;
+  justify-content: space-between;
+  padding: 22px 0;
+}
+.strip__label {
+  font-size: 12px;
+  letter-spacing: 0.14em;
+  text-transform: uppercase;
+  color: var(--color-muted);
+}
+.strip__items {
+  display: flex;
+  gap: clamp(20px, 4vw, 40px);
+  flex-wrap: wrap;
+  align-items: center;
+}
+.strip__items span {
+  font-family: var(--font-serif);
+  font-size: 18px;
+  font-weight: 500;
+  color: var(--color-ink-soft);
+  letter-spacing: -0.01em;
+}
+
+/* ============================================================
+   Section heading
+   ============================================================ */
+.section {
+  padding: clamp(48px, 7vw, 88px) 0;
+}
+.section--alt {
+  background: var(--color-surface);
+  border-block: 1px solid var(--color-line);
+}
+.section__head {
+  display: grid;
+  gap: var(--space-4);
+  grid-template-columns: 1fr;
+  align-items: end;
+  margin-bottom: var(--space-6);
+}
+@media (min-width: 760px) {
+  .section__head {
+    grid-template-columns: 1fr auto;
+  }
+}
+.section__title {
+  font-family: var(--font-serif);
+  font-weight: 500;
+  font-size: clamp(28px, 3.6vw, 44px);
+  letter-spacing: -0.02em;
+  line-height: 1.05;
+  margin: 0;
+  max-width: 18ch;
+}
+.section__sub {
+  margin: 8px 0 0;
+  color: var(--color-muted);
+  max-width: 56ch;
+}
+
+/* ============================================================
+   Category tabs (featured products)
+   ============================================================ */
+.tabs {
+  display: flex;
+  gap: 6px;
+  flex-wrap: wrap;
+  background: var(--color-surface-2);
+  padding: 6px;
+  border-radius: 999px;
+  width: max-content;
+  max-width: 100%;
+}
+.tabs__btn {
+  padding: 9px 16px;
+  border-radius: 999px;
+  font-weight: 500;
+  font-size: 14px;
+  color: var(--color-ink-soft);
+  transition: background 0.18s var(--ease), color 0.18s var(--ease);
+}
+.tabs__btn[aria-selected="true"] {
+  background: var(--color-ink);
+  color: #fff;
+}
+.tabs__btn:hover:not([aria-selected="true"]) {
+  background: rgba(0, 0, 0, 0.05);
+}
+
+/* ============================================================
+   Product grid
+   ============================================================ */
+.products {
+  display: grid;
+  gap: var(--space-5);
+  grid-template-columns: repeat(1, 1fr);
+}
+@media (min-width: 560px) {
+  .products {
+    grid-template-columns: repeat(2, 1fr);
+  }
+}
+@media (min-width: 920px) {
+  .products {
+    grid-template-columns: repeat(3, 1fr);
+  }
+}
+@media (min-width: 1140px) {
+  .products {
+    grid-template-columns: repeat(4, 1fr);
+  }
+}
+
+.product {
+  display: flex;
+  flex-direction: column;
+  gap: var(--space-3);
+  position: relative;
+}
+.product__media {
+  position: relative;
+  aspect-ratio: 4 / 5;
+  border-radius: var(--radius-lg);
+  background: var(--color-surface-2);
+  overflow: hidden;
+  isolation: isolate;
+}
+.product__art {
+  position: absolute;
+  inset: 0;
+  display: grid;
+  place-items: center;
+  transition: transform 0.6s var(--ease);
+}
+.product:hover .product__art {
+  transform: scale(1.04);
+}
+.product__badges {
+  position: absolute;
+  top: 12px;
+  left: 12px;
+  display: flex;
+  flex-direction: column;
+  gap: 6px;
+  z-index: 2;
+}
+.badge {
+  display: inline-flex;
+  align-items: center;
+  gap: 6px;
+  font-size: 11px;
+  font-weight: 700;
+  letter-spacing: 0.06em;
+  text-transform: uppercase;
+  padding: 6px 10px;
+  border-radius: 999px;
+  background: #fff;
+  color: var(--color-ink);
+  border: 1px solid var(--color-line);
+}
+.badge--new {
+  background: var(--color-ink);
+  color: #fff;
+  border-color: var(--color-ink);
+}
+.badge--sale {
+  background: var(--color-sale);
+  color: #fff;
+  border-color: var(--color-sale);
+}
+.badge--low {
+  background: #fff5e6;
+  color: #8a5a10;
+  border-color: #f0d8a8;
+}
+
+.product__quick {
+  position: absolute;
+  inset: auto 12px 12px;
+  display: flex;
+  gap: 8px;
+  z-index: 2;
+  opacity: 0;
+  transform: translateY(8px);
+  transition: opacity 0.2s var(--ease), transform 0.2s var(--ease);
+}
+.product:hover .product__quick,
+.product:focus-within .product__quick {
+  opacity: 1;
+  transform: translateY(0);
+}
+.product__quick .btn {
+  flex: 1;
+  height: 42px;
+  font-size: 13.5px;
+}
+
+.product__wish {
+  position: absolute;
+  top: 12px;
+  right: 12px;
+  width: 36px;
+  height: 36px;
+  border-radius: 999px;
+  background: rgba(255, 255, 255, 0.9);
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  z-index: 2;
+  transition: background 0.18s var(--ease), color 0.18s var(--ease);
+  color: var(--color-ink);
+  border: 1px solid var(--color-line);
+}
+.product__wish:hover {
+  background: #fff;
+}
+.product__wish[aria-pressed="true"] {
+  background: var(--color-accent);
+  color: #fff;
+  border-color: var(--color-accent);
+}
+.product__wish svg {
+  width: 18px;
+  height: 18px;
+}
+
+.product__info {
+  display: flex;
+  flex-direction: column;
+  gap: 4px;
+}
+.product__category {
+  font-size: 12px;
+  letter-spacing: 0.08em;
+  text-transform: uppercase;
+  color: var(--color-muted);
+}
+.product__name {
+  font-family: var(--font-serif);
+  font-size: 18px;
+  font-weight: 500;
+  letter-spacing: -0.01em;
+  margin: 0;
+  line-height: 1.25;
+}
+.product__name a {
+  text-decoration: none;
+  color: inherit;
+}
+.product__name a:hover {
+  text-decoration: underline;
+}
+.product__name a::after {
+  content: "";
+  position: absolute;
+  inset: 0;
+}
+.product__row {
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: 12px;
+  margin-top: 2px;
+}
+.product__price {
+  display: flex;
+  align-items: baseline;
+  gap: 8px;
+}
+.product__price .now {
+  font-weight: 600;
+  font-size: 16px;
+}
+.product__price .was {
+  text-decoration: line-through;
+  color: var(--color-muted);
+  font-size: 13px;
+}
+.product__rating {
+  display: inline-flex;
+  align-items: center;
+  gap: 5px;
+  font-size: 13px;
+  color: var(--color-muted);
+}
+.product__rating svg {
+  width: 14px;
+  height: 14px;
+  color: #d4a017;
+}
+
+/* Product art (CSS-only "imagery") */
+.art {
+  width: 70%;
+  aspect-ratio: 1 / 1;
+  border-radius: 50%;
+  background: linear-gradient(135deg, var(--a, #e6dcc7), var(--b, #c8b791));
+  position: relative;
+  display: grid;
+  place-items: center;
+  box-shadow: inset 0 0 60px rgba(0, 0, 0, 0.08);
+}
+.art--mug { --a: #f3e2c4; --b: #c79a5e; border-radius: 36% 36% 32% 32% / 30% 30% 50% 50%; width: 55%; aspect-ratio: 4/5; }
+.art--mug::after { content:""; position:absolute; right: -14%; top: 30%; width: 28%; aspect-ratio: 1; border: 6px solid #c79a5e; border-radius: 50%; background: transparent; }
+.art--lamp { --a: #fff7e0; --b: #e3c982; border-radius: 50% 50% 12% 12% / 60% 60% 12% 12%; width: 45%; aspect-ratio: 3/4; }
+.art--lamp::before { content:""; position:absolute; bottom:-18%; left:50%; transform:translateX(-50%); width:40%; height:30%; background:#3b342a; border-radius:6px 6px 16px 16px; }
+.art--bottle { --a: #d9e6db; --b: #6f8a72; border-radius: 30% 30% 18% 18% / 18% 18% 18% 18%; width: 32%; aspect-ratio: 2/5; }
+.art--bottle::before { content:""; position:absolute; top:-16%; left:50%; transform:translateX(-50%); width:40%; height:18%; background:#3a4a3b; border-radius:6px;}
+.art--chair { --a: #efe1cc; --b: #b48a55; border-radius: 18% 18% 8% 8% / 24% 24% 8% 8%; width: 60%; aspect-ratio: 1/1; }
+.art--candle { --a: #f6e9d1; --b: #d8b06c; border-radius: 24%; width: 38%; aspect-ratio: 1/1.2; }
