  .announce__sep {
    display: inline;
  }
}
.announce__item {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}
.announce a {
  color: inherit;
}

/* ============================================================
   Header / nav
   ============================================================ */
.header {
  position: sticky;
  top: 0;
  z-index: 50;
  background: color-mix(in srgb, var(--color-bg) 88%, transparent);
  backdrop-filter: saturate(140%) blur(10px);
  border-bottom: 1px solid var(--color-line);
}
.header__inner {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: var(--space-4);
  height: 72px;
}
