  display: flex;
  align-items: center;
  gap: 4px;
}
.icon-btn {
  position: relative;
  width: 40px;
  height: 40px;
  border-radius: 999px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--color-ink);
  transition: background 0.18s var(--ease);
}
.icon-btn:hover {
  background: var(--color-surface-2);
}
.icon-btn svg {
  width: 20px;
  height: 20px;
}
.icon-btn .cart-count {
  position: absolute;
  top: 4px;
  right: 4px;
  min-width: 18px;
  height: 18px;
  padding: 0 5px;
  border-radius: 999px;
  background: var(--color-accent);
  color: #fff;
  font-size: 11px;
  font-weight: 700;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
}
.menu-toggle {
  display: inline-flex;
}
@media (min-width: 900px) {
  .menu-toggle {
    display: none;
  }
}

/* Mobile drawer */
.mobile-nav {
  border-top: 1px solid var(--color-line);
  background: var(--color-bg);
}
.mobile-nav__list {
  list-style: none;
  margin: 0;
  padding: var(--space-3) var(--shell-pad) var(--space-5);
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.mobile-nav a {
  display: block;
  padding: 14px 12px;
  border-radius: 10px;
  text-decoration: none;
  font-weight: 500;
  color: var(--color-ink-soft);
}
.mobile-nav a:hover {
  background: var(--color-surface-2);
}

/* ============================================================
   Hero
   ============================================================ */
.hero {
  padding: clamp(28px, 4vw, 56px) 0 clamp(40px, 6vw, 72px);
}
.hero__grid {
  display: grid;
  gap: var(--space-5);
  grid-template-columns: 1fr;
}
@media (min-width: 960px) {
  .hero__grid {
    grid-template-columns: 1.05fr 1fr;
    gap: var(--space-7);
    align-items: stretch;
  }
}
.hero__copy {
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 8px 0;
}
.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--color-muted);
  margin-bottom: var(--space-4);
}
.eyebrow::before {
  content: "";
  width: 24px;
  height: 1px;
  background: currentColor;
}
.hero__title {
  font-family: var(--font-serif);
  font-weight: 500;
  font-size: clamp(40px, 6.4vw, 76px);
  line-height: 1.02;
  letter-spacing: -0.02em;
  margin: 0 0 var(--space-4);
  color: var(--color-ink);
}
.hero__title em {
  font-style: italic;
  color: var(--color-accent);
  font-weight: 400;
}
.hero__lede {
  font-size: clamp(16px, 1.5vw, 18px);
  color: var(--color-muted);
  max-width: 52ch;
  margin: 0 0 var(--space-6);
}
.hero__cta {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-3);
  margin-bottom: var(--space-6);
}
.hero__meta {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-5);
  padding-top: var(--space-5);
  border-top: 1px solid var(--color-line);
}
.hero__meta dt {
  font-size: 12px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--color-muted);
  margin-bottom: 4px;
}
.hero__meta dd {
  margin: 0;
  font-family: var(--font-serif);
  font-weight: 500;
  font-size: 22px;
  letter-spacing: -0.01em;
}

.hero__visual {
  position: relative;
  border-radius: var(--radius-xl);
  overflow: hidden;
  aspect-ratio: 4 / 5;
  background: linear-gradient(160deg, #d9d3c5 0%, #c0bba9 60%, #aaa491 100%);
  min-height: 420px;
}
.hero__visual::after {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(
      120% 80% at 80% 0%,
      rgba(255, 255, 255, 0.35),
      transparent 60%
    ),
    radial-gradient(80% 60% at 10% 100%, rgba(20, 21, 15, 0.25), transparent 70%);
  pointer-events: none;
}
.hero__visual-inner {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  padding: var(--space-6);
}
.hero__chip {
  position: absolute;
  background: rgba(255, 255, 255, 0.92);
  backdrop-filter: blur(6px);
  border-radius: 14px;
  padding: 12px 14px;
  font-size: 13px;
  display: flex;
  align-items: center;
  gap: 10px;
  box-shadow: 0 10px 30px -12px rgba(20, 21, 15, 0.25);
  border: 1px solid rgba(255, 255, 255, 0.6);
}
.hero__chip strong {
  font-weight: 600;
}
.hero__chip--tl {
  top: 20px;
  left: 20px;
}
.hero__chip--br {
  bottom: 24px;
  right: 24px;
}
.hero__chip__dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--color-success);
  box-shadow: 0 0 0 4px rgba(46, 107, 62, 0.18);
}
.hero__product-card {
  background: rgba(255, 255, 255, 0.96);
  border-radius: var(--radius-lg);
  padding: 18px;
  width: min(280px, 80%);
  box-shadow: 0 30px 60px -25px rgba(20, 21, 15, 0.35);
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.hero__product-card .pcard__img {
  aspect-ratio: 1 / 1;
  border-radius: 12px;
  background: linear-gradient(135deg, #efe5d2, #d9c9a6);
  display: grid;
  place-items: center;
}
.hero__product-card .pcard__name {
  font-family: var(--font-serif);
  font-size: 18px;
  font-weight: 500;
  margin: 6px 0 0;
}
.hero__product-card .pcard__row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 13px;
  color: var(--color-muted);
}
.hero__product-card .pcard__row strong {
  color: var(--color-ink);
  font-weight: 600;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  height: 48px;
  padding: 0 22px;
  border-radius: 999px;
  font-weight: 600;
  font-size: 15px;
  text-decoration: none;
  border: 1px solid transparent;
  transition: transform 0.15s var(--ease), background 0.18s var(--ease),
    color 0.18s var(--ease), border-color 0.18s var(--ease);
  white-space: nowrap;
}
.btn:active {
  transform: translateY(1px);
}
.btn--primary {
  background: var(--color-ink);
  color: #fff;
}
.btn--primary:hover {
  background: var(--color-ink-soft);
}
.btn--secondary {
  background: transparent;
  border-color: var(--color-line-strong);
  color: var(--color-ink);
}
.btn--secondary:hover {
  background: var(--color-surface);
  border-color: var(--color-ink);
}
.btn--accent {
  background: var(--color-accent);
  color: #fff;
}
.btn--accent:hover {
  background: var(--color-accent-ink);
}
.btn--sm {
  height: 38px;
  padding: 0 16px;
  font-size: 13.5px;
}
.btn--ghost {
  background: transparent;
  color: var(--color-ink);
}
.btn--ghost:hover {
  background: var(--color-surface-2);
}

/* ============================================================
   Marquee / brand strip
   ============================================================ */
.strip {
  border-block: 1px solid var(--color-line);
  background: var(--color-surface);
}
.strip__inner {
  display: flex;
  align-items: center;
  gap: clamp(24px, 5vw, 56px);
  flex-wrap: wrap;
  justify-content: space-between;
  padding: 22px 0;
}
.strip__label {
  font-size: 12px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--color-muted);
}
.strip__items {
  display: flex;
  gap: clamp(20px, 4vw, 40px);
  flex-wrap: wrap;
  align-items: center;
}
.strip__items span {
  font-family: var(--font-serif);
  font-size: 18px;
  font-weight: 500;
  color: var(--color-ink-soft);
  letter-spacing: -0.01em;
}

/* ============================================================
   Section heading
   ============================================================ */
.section {
  padding: clamp(48px, 7vw, 88px) 0;
}
.section--alt {
  background: var(--color-surface);
  border-block: 1px solid var(--color-line);
}
.section__head {
  display: grid;
  gap: var(--space-4);
  grid-template-columns: 1fr;
  align-items: end;
  margin-bottom: var(--space-6);
}
@media (min-width: 760px) {
  .section__head {
    grid-template-columns: 1fr auto;
  }
}
.section__title {
  font-family: var(--font-serif);
  font-weight: 500;
  font-size: clamp(28px, 3.6vw, 44px);
  letter-spacing: -0.02em;
  line-height: 1.05;
  margin: 0;
  max-width: 18ch;
}
.section__sub {
  margin: 8px 0 0;
  color: var(--color-muted);
  max-width: 56ch;
}

/* ============================================================
   Category tabs (featured products)
   ============================================================ */
.tabs {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
  background: var(--color-surface-2);
  padding: 6px;
  border-radius: 999px;
  width: max-content;
  max-width: 100%;
}
.tabs__btn {
  padding: 9px 16px;
  border-radius: 999px;
  font-weight: 500;
  font-size: 14px;
  color: var(--color-ink-soft);
  transition: background 0.18s var(--ease), color 0.18s var(--ease);
}
.tabs__btn[aria-selected="true"] {
  background: var(--color-ink);
  color: #fff;
}
.tabs__btn:hover:not([aria-selected="true"]) {
  background: rgba(0, 0, 0, 0.05);
}

/* ============================================================
   Product grid
   ============================================================ */
.products {
  display: grid;
  gap: var(--space-5);
  grid-template-columns: repeat(1, 1fr);
}
@media (min-width: 560px) {
  .products {
    grid-template-columns: repeat(2, 1fr);
  }
}
@media (min-width: 920px) {
  .products {
    grid-template-columns: repeat(3, 1fr);
  }
}
@media (min-width: 1140px) {
  .products {
    grid-template-columns: repeat(4, 1fr);
  }
}

.product {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
  position: relative;
}
.product__media {
  position: relative;
  aspect-ratio: 4 / 5;
  border-radius: var(--radius-lg);
  background: var(--color-surface-2);
  overflow: hidden;
  isolation: isolate;
}
.product__art {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  transition: transform 0.6s var(--ease);
}
.product:hover .product__art {
  transform: scale(1.04);
}
.product__badges {
  position: absolute;
  top: 12px;
  left: 12px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  z-index: 2;
}
.badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: 6px 10px;
  border-radius: 999px;
  background: #fff;
  color: var(--color-ink);
  border: 1px solid var(--color-line);
}
.badge--new {
  background: var(--color-ink);
  color: #fff;
  border-color: var(--color-ink);
}
.badge--sale {
  background: var(--color-sale);
  color: #fff;
  border-color: var(--color-sale);
}
.badge--low {
  background: #fff5e6;
  color: #8a5a10;
  border-color: #f0d8a8;
}

.product__quick {
  position: absolute;
  inset: auto 12px 12px;
  display: flex;
  gap: 8px;
  z-index: 2;
  opacity: 0;
  transform: translateY(8px);
  transition: opacity 0.2s var(--ease), transform 0.2s var(--ease);
}
.product:hover .product__quick,
.product:focus-within .product__quick {
  opacity: 1;
  transform: translateY(0);
}
.product__quick .btn {
  flex: 1;
  height: 42px;
  font-size: 13.5px;
}

.product__wish {
  position: absolute;
  top: 12px;
  right: 12px;
  width: 36px;
  height: 36px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.9);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  z-index: 2;
  transition: background 0.18s var(--ease), color 0.18s var(--ease);
  color: var(--color-ink);
  border: 1px solid var(--color-line);
}
.product__wish:hover {
  background: #fff;
}
.product__wish[aria-pressed="true"] {
  background: var(--color-accent);
  color: #fff;
  border-color: var(--color-accent);
}
.product__wish svg {
  width: 18px;
  height: 18px;
}

.product__info {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.product__category {
  font-size: 12px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--color-muted);
}
.product__name {
  font-family: var(--font-serif);
  font-size: 18px;
  font-weight: 500;
  letter-spacing: -0.01em;
  margin: 0;
  line-height: 1.25;
}
.product__name a {
  text-decoration: none;
  color: inherit;
}
.product__name a:hover {
  text-decoration: underline;
}
.product__name a::after {
  content: "";
  position: absolute;
  inset: 0;
}
.product__row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-top: 2px;
}
.product__price {
  display: flex;
  align-items: baseline;
  gap: 8px;
}
.product__price .now {
  font-weight: 600;
  font-size: 16px;
}
.product__price .was {
  text-decoration: line-through;
  color: var(--color-muted);
  font-size: 13px;
}
.product__rating {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 13px;
  color: var(--color-muted);
}
.product__rating svg {
  width: 14px;
  height: 14px;
  color: #d4a017;
}

/* Product art (CSS-only "imagery") */
.art {
  width: 70%;
  aspect-ratio: 1 / 1;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--a, #e6dcc7), var(--b, #c8b791));
  position: relative;
  display: grid;
  place-items: center;
  box-shadow: inset 0 0 60px rgba(0, 0, 0, 0.08);
}
.art--mug { --a: #f3e2c4; --b: #c79a5e; border-radius: 36% 36% 32% 32% / 30% 30% 50% 50%; width: 55%; aspect-ratio: 4/5; }
.art--mug::after { content:""; position:absolute; right: -14%; top: 30%; width: 28%; aspect-ratio: 1; border: 6px solid #c79a5e; border-radius: 50%; background: transparent; }
.art--lamp { --a: #fff7e0; --b: #e3c982; border-radius: 50% 50% 12% 12% / 60% 60% 12% 12%; width: 45%; aspect-ratio: 3/4; }
.art--lamp::before { content:""; position:absolute; bottom:-18%; left:50%; transform:translateX(-50%); width:40%; height:30%; background:#3b342a; border-radius:6px 6px 16px 16px; }
.art--bottle { --a: #d9e6db; --b: #6f8a72; border-radius: 30% 30% 18% 18% / 18% 18% 18% 18%; width: 32%; aspect-ratio: 2/5; }
.art--bottle::before { content:""; position:absolute; top:-16%; left:50%; transform:translateX(-50%); width:40%; height:18%; background:#3a4a3b; border-radius:6px;}
.art--chair { --a: #efe1cc; --b: #b48a55; border-radius: 18% 18% 8% 8% / 24% 24% 8% 8%; width: 60%; aspect-ratio: 1/1; }
.art--candle { --a: #f6e9d1; --b: #d8b06c; border-radius: 24%; width: 38%; aspect-ratio: 1/1.2; }
.art--candle::before { content:""; position:absolute; top:-22%; left:50%; transform:translateX(-50%); width:6px; height:18%; background:#3b2a14; border-radius:3px;}
.art--candle::after { content:""; position:absolute; top:-32%; left:50%; transform:translateX(-50%); width:10px; height:14px; background:radial-gradient(circle at 50% 70%, #ffd76b, #c97216); border-radius:50% 50% 50% 50% / 60% 60% 40% 40%;}
.art--bowl { --a: #f1e6d4; --b: #b89976; border-radius: 50% 50% 46% 46% / 28% 28% 70% 70%; width: 70%; aspect-ratio: 2/1; }
.art--throw { --a: #e9d3b6; --b: #a86b3a; border-radius: 14px; width: 70%; aspect-ratio: 1/1.1; background-image: repeating-linear-gradient(45deg, rgba(255,255,255,0.18) 0 6px, transparent 6px 14px), linear-gradient(135deg, var(--a), var(--b)); }
.art--vase { --a: #e9e3d2; --b: #8a7a55; border-radius: 50% 50% 28% 28% / 22% 22% 50% 50%; width: 40%; aspect-ratio: 2/3; }
.art--knife { --a: #ece6d8; --b: #6e6a5e; border-radius: 8px; width: 18%; aspect-ratio: 1/4; }
.art--knife::after { content:""; position:absolute; bottom:-6%; left:50%; transform:translateX(-50%); width:140%; height:16%; background:#2a221a; border-radius:4px;}
.art--basket { --a: #f0dfb8; --b: #8c5a25; border-radius: 14% 14% 30% 30% / 14% 14% 60% 60%; width: 70%; aspect-ratio: 5/4; background-image: repeating-linear-gradient(0deg, rgba(0,0,0,0.08) 0 2px, transparent 2px 8px), linear-gradient(135deg, var(--a), var(--b));}
.art--frame { --a: #efe5d4; --b: #cbb990; border-radius: 6px; width: 70%; aspect-ratio: 4/5; box-shadow: inset 0 0 0 12px var(--b), inset 0 0 0 14px #fff; }

/* ============================================================
   Deals
   ============================================================ */
.deals {
  display: grid;
  gap: var(--space-4);
  grid-template-columns: 1fr;
}
@media (min-width: 760px) {
  .deals {
    grid-template-columns: 1.3fr 1fr;
  }
}
@media (min-width: 1080px) {
  .deals {
    grid-template-columns: 1.6fr 1fr 1fr;
    grid-auto-rows: 1fr;
  }
}

.deal {
  border-radius: var(--radius-lg);
  padding: clamp(20px, 2.5vw, 32px);
  position: relative;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  min-height: 280px;
  isolation: isolate;
  color: var(--color-ink);
}
.deal--feature {
  grid-column: 1 / -1;
  background: linear-gradient(135deg, #1f1d18 0%, #2c2a23 60%, #3a382f 100%);
  color: #f6f1e6;
  min-height: 360px;
}
@media (min-width: 1080px) {
  .deal--feature {
    grid-column: span 1;
    min-height: 100%;
  }
}
.deal--warm {
  background: linear-gradient(135deg, #f1e3cb 0%, #e3c89c 100%);
}
.deal--sage {
  background: linear-gradient(135deg, #e3ebdd 0%, #b8c9af 100%);
}
.deal__kicker {
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  margin-bottom: 14px;
  display: inline-flex;
  align-items: center;
  gap: 10px;
}
.deal__kicker .dot {
  width: 6px;
  height: 6px;
  background: var(--color-accent);
  border-radius: 50%;
}
.deal--feature .deal__kicker .dot {
  background: #ff9a6c;
}
.deal__title {
  font-family: var(--font-serif);
  font-size: clamp(26px, 3vw, 38px);
  font-weight: 500;
  letter-spacing: -0.02em;
  line-height: 1.05;
  margin: 0 0 var(--space-3);
}
.deal__lede {
  margin: 0 0 var(--space-5);
  max-width: 38ch;
  color: inherit;
  opacity: 0.9;
}
.deal__lede--muted {
  color: var(--color-ink-soft);
  opacity: 1;
}
.deal__row {
  display: flex;
  justify-content: space-between;
  align-items: end;
  gap: var(--space-4);
  flex-wrap: wrap;
}
.countdown {
  display: flex;
  gap: 8px;
  margin: 0 0 var(--space-5);
}
.countdown__cell {
  background: rgba(255, 255, 255, 0.1);
  border: 1px solid rgba(255, 255, 255, 0.16);
  padding: 10px 12px;
  border-radius: 10px;
  text-align: center;
  min-width: 56px;
}
.countdown__cell strong {
  display: block;
  font-family: var(--font-serif);
  font-size: 22px;
  font-weight: 500;
  line-height: 1;
}
.countdown__cell span {
  display: block;
  font-size: 10px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  margin-top: 6px;
  opacity: 0.7;
}
.deal--feature .btn--primary {
  background: #f6f1e6;
  color: var(--color-ink);
}
.deal--feature .btn--primary:hover {
  background: #fff;
}
.deal__price {
  display: flex;
  align-items: baseline;
  gap: 10px;
}
.deal__price .now {
  font-family: var(--font-serif);
  font-size: 30px;
  font-weight: 500;
  letter-spacing: -0.01em;
}
.deal__price .was {
  text-decoration: line-through;
  color: var(--color-muted);
}
.deal__bg {
  position: absolute;
  right: -40px;
  bottom: -40px;
  width: 220px;
  height: 220px;
  border-radius: 50%;
  opacity: 0.4;
  z-index: -1;
}
.deal--feature .deal__bg {
  background: radial-gradient(circle, #b94d2a 0%, transparent 70%);
  opacity: 0.7;
}
.deal--warm .deal__bg {
  background: radial-gradient(circle, #fff 0%, transparent 70%);
}
.deal--sage .deal__bg {
  background: radial-gradient(circle, #fff 0%, transparent 70%);
}

/* ============================================================
   Editorial
