+  .deal--feature {
+    grid-column: span 1;
+    min-height: 100%;
+  }
+}
+.deal--warm {
+  background: linear-gradient(135deg, #f1e3cb 0%, #e3c89c 100%);
+}
+.deal--sage {
+  background: linear-gradient(135deg, #e3ebdd 0%, #b8c9af 100%);
+}
+.deal__kicker {
+  font-size: 12px;
+  font-weight: 600;
+  letter-spacing: 0.14em;
+  text-transform: uppercase;
+  margin-bottom: 14px;
+  display: inline-flex;
+  align-items: center;
+  gap: 10px;
+}
+.deal__kicker .dot {
+  width: 6px;
+  height: 6px;
