+
+/* ============================================================
+   Editorial
+   ============================================================ */
+.editorial {
+  display: grid;
+  gap: var(--space-5);
+  grid-template-columns: 1fr;
+}
+@media (min-width: 820px) {
+  .editorial {
+    grid-template-columns: 1.4fr 1fr 1fr;
+  }
+}
+.article {
+  display: flex;
+  flex-direction: column;
+  gap: var(--space-3);
+  text-decoration: none;
+  color: inherit;
+  border-radius: var(--radius-lg);
