const Newsletter = ({ onSubscribe }) => {
  const [email, setEmail] = useState("");
  const [status, setStatus] = useState({ type: "idle", message: "" });
  const inputRef = useRef(null);

  const handleSubmit = (e) => {
    e.preventDefault();
    const value = email.trim();
    const valid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
    if (!valid) {
      setStatus({ type: "error", message: "Please enter a valid email address." });
      inputRef.current?.focus();
      return;
    }
    setStatus({ type: "success", message: "Thanks — please check your inbox to confirm." });
    setEmail("");
    onSubscribe?.(value);
  };

  const hintId = "newsletter-hint";
  return (
    <section className="section" aria-labelledby="news-title">
      <div className="shell">
        <div className="newsletter">
          <div>
            <h2 id="news-title">Slow letters,<br /> first dibs.</h2>
            <p>
              One thoughtful email a month: new arrivals, restocks, and the
              stories behind them. No noise — unsubscribe any time.
            </p>
          </div>
          <form className="subscribe" onSubmit={handleSubmit} noValidate>
            <label htmlFor="newsletter-email" className="sr-only">
              Email address
            </label>
            <div className="subscribe__row">
              <input
                ref={inputRef}
                id="newsletter-email"
                type="email"
                inputMode="email"
                autoComplete="email"
                placeholder="you@example.com"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                aria-describedby={hintId}
                aria-invalid={status.type === "error"}
                required
              />
              <button type="submit" className="btn btn--accent">
                Subscribe
              </button>
            </div>
            <p
              id={hintId}
              className={
                "subscribe__hint" +
                (status.type === "error" ? " subscribe__hint--error" : "") +
                (status.type === "success" ? " subscribe__hint--success" : "")
              }
              role={status.type === "error" ? "alert" : undefined}
              aria-live={status.type === "success" ? "polite" : undefined}
            >
              {status.message ||
                "By subscribing you agree to our privacy policy. We'll never share your address."}
            </p>
          </form>
        </div>
      </div>
    </section>
  );
};

