/* ------------------------------------------------------------------
 * App
 * ------------------------------------------------------------------ */
const App = () => {
  const [cart, setCart] = useState([]);
  const [wishlist, setWishlist] = useState(() => new Set());
  const [toasts, setToasts] = useState([]);

  const pushToast = useCallback((message) => {
    const id = Math.random().toString(36).slice(2);
    setToasts((t) => [...t, { id, message }]);
    setTimeout(() => setToasts((t) => t.filter((x) => x.id !== id)), 2600);
  }, []);

  const handleAdd = useCallback((p) => {
    setCart((c) => [...c, p.id]);
    pushToast(`Added "${p.name}" to your bag`);
  }, [pushToast]);

  const handleWish = useCallback((id) => {
    setWishlist((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  }, []);

  return (
    <>
      <AnnouncementBar />
      <Header
        cartCount={cart.length}
        onOpenCart={() => pushToast(`Bag: ${cart.length} item${cart.length===1?"":"s"}`)}
        onOpenSearch={() => pushToast("Search coming soon")}
      />
      <main id="main">
        <Hero />
        <BrandStrip />
        <FeaturedProducts onAdd={handleAdd} wishlist={wishlist} onWish={handleWish} />
        <Deals />
        <Editorial />
        <Values />
        <Newsletter onSubscribe={(e) => pushToast(`Subscribed ${e}`)} />
      </main>
      <Footer />
      <Toasts toasts={toasts} />
    </>
  );
};

